import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"cli/index.md","filePath":"cli/index.md","lastUpdated":1791840224000}'),c={name:"cli/index.md"};function i(r,e,n,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The <code>mfe-forge</code> package ships a single command-line program that scaffolds, runs, builds, synchronizes, and inspects an MFE Forge workspace. This section documents the behavior of the current implementation (<code>packages/cli</code>, version 0.1.x). Where a flag is accepted but not yet implemented, the page says so explicitly.</p><h2 id="installation-and-invocation" tabindex="-1">Installation and invocation <a class="header-anchor" href="#installation-and-invocation" aria-label="Permalink to &quot;Installation and invocation&quot;">​</a></h2><p>The package registers two equivalent binaries:</p><table tabindex="0"><thead><tr><th>Binary</th><th>Notes</th></tr></thead><tbody><tr><td><code>mfe-forge</code></td><td>Canonical name, used throughout these docs.</td></tr><tr><td><code>mfe</code></td><td>Short alias pointing at the same entry point (<code>dist/bin/index.js</code>).</td></tr></tbody></table><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-030fh" id="tab-kJufmiY" checked><label data-title="bun" for="tab-kJufmiY">bun</label><input type="radio" name="group-030fh" id="tab-lT3N2qg"><label data-title="pnpm" for="tab-lT3N2qg">pnpm</label><input type="radio" name="group-030fh" id="tab-hkLuIOK"><label data-title="npm" for="tab-hkLuIOK">npm</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div></div></div><p>See <a href="./../installation">Installation</a> for installing the CLI globally or as a workspace dev dependency.</p><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge &lt;command&gt; [options]</span></span>
<span class="line"><span>mfe-forge --version</span></span>
<span class="line"><span>mfe-forge --help</span></span>
<span class="line"><span>mfe-forge help [command]</span></span></code></pre></div><h2 id="working-directory" tabindex="-1">Working directory <a class="header-anchor" href="#working-directory" aria-label="Permalink to &quot;Working directory&quot;">​</a></h2><p>Every command except <code>init</code> treats the <strong>current working directory as the project root</strong>. The CLI does not walk up the directory tree looking for a project:</p><ul><li>configuration is loaded from the current directory (see <a href="./../config">Configuration</a>);</li><li>applications are discovered under <code>./apps/&lt;scope&gt;/&lt;name&gt;/</code>;</li><li>packages are discovered under <code>./packages/&lt;name&gt;/</code>;</li><li>the manifest is written to <code>./mfe-forge.manifest.json</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Run commands from the workspace root. Running them from inside <code>apps/shop/cart</code> makes the CLI treat that directory as an empty project.</p></div><h2 id="global-options" tabindex="-1">Global options <a class="header-anchor" href="#global-options" aria-label="Permalink to &quot;Global options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>-v</code>, <code>--version</code></td><td>Print the CLI version and exit with code <code>0</code>.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Print help for the program or for a command and exit with code <code>0</code>.</td></tr></tbody></table><p>There are no other global options. Flags such as <code>--json</code> are defined per command; check each command page.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th><th>Page</th></tr></thead><tbody><tr><td><code>init [name]</code></td><td>Create a new workspace skeleton.</td><td><a href="./init">init</a></td></tr><tr><td><code>generate &lt;type&gt; [name]</code> (alias <code>g</code>)</td><td>Scaffold an app, host, package, library, or design system.</td><td><a href="./generate">generate</a></td></tr><tr><td><code>dev</code></td><td>Start development servers through generated root scripts.</td><td><a href="./dev">dev</a></td></tr><tr><td><code>build [app]</code></td><td>Run each app&#39;s <code>build</code> script and report failures.</td><td><a href="./build">build</a></td></tr><tr><td><code>test [app]</code></td><td>Run the <code>test</code>, <code>test:unit</code>, or <code>test:e2e</code> script.</td><td><a href="./build#mfe-forge-test">build</a></td></tr><tr><td><code>sync</code></td><td>Reconcile host remotes, remote type declarations, and the manifest.</td><td><a href="./sync">sync</a></td></tr><tr><td><code>doctor</code></td><td>Run environment and topology health checks.</td><td><a href="./doctor">doctor</a></td></tr><tr><td><code>config</code></td><td>Read, write, validate, or interactively edit configuration.</td><td><a href="./config">config</a></td></tr><tr><td><code>status</code>, <code>graph</code>, <code>inspect</code>, <code>deps</code>, <code>check</code>, <code>migrate</code></td><td>Topology and manifest inspection tools.</td><td><a href="./diagnostics">diagnostics</a></td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><p>Exit codes are defined in <code>packages/cli/src/utils/exit.ts</code> (<code>ExitCode</code>) and are also exported from the package entry point.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>Ok</code></td><td>Success. Also returned for <code>--help</code> and <code>--version</code>.</td></tr><tr><td><code>1</code></td><td><code>UserError</code></td><td>Invalid input (unknown command or option, missing argument, unknown app, invalid generator type), or a check-style command found a problem (<code>sync --check</code>, <code>check</code>, <code>deps --check</code>, <code>config --validate</code>, <code>inspect</code> with an unknown app).</td></tr><tr><td><code>2</code></td><td><code>TaskFailed</code></td><td>Delegated work failed: a build, a test run, a dev server process, or a <code>doctor</code> check.</td></tr><tr><td><code>3</code></td><td><code>ConfigError</code></td><td>The configuration was loaded but failed schema validation.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Some commands (<code>init</code>, <code>generate</code>, <code>config --set</code> without <code>--value</code>) report errors by exiting with <code>1</code> directly, so their messages are printed without the <code>❌ Error:</code> prefix used by other commands. The exit code is still <code>1</code>.</p></div><p>Uncaught errors that are not <code>CliError</code> instances are printed as <code>❌ Error: &lt;message&gt;</code> and exit with <code>1</code>.</p><h2 id="output-modes" tabindex="-1">Output modes <a class="header-anchor" href="#output-modes" aria-label="Permalink to &quot;Output modes&quot;">​</a></h2><p>Human output is colored (via <code>chalk</code>) and may include spinners and emoji. <strong>Do not parse it.</strong> For automation, use the machine-readable mode where a command offers one:</p><table tabindex="0"><thead><tr><th>Command</th><th>Machine-readable flag</th><th>Output</th></tr></thead><tbody><tr><td><code>sync</code></td><td><code>--json</code></td><td><code>{ changed, files, dryRun }</code></td></tr><tr><td><code>doctor</code></td><td><code>--json</code></td><td><code>{ ok, summary, checks }</code></td></tr><tr><td><code>config</code></td><td><code>--json</code> (with <code>--show</code>, <code>--get</code>, <code>--set</code>, <code>--validate</code>)</td><td>JSON value or result object</td></tr><tr><td><code>status</code></td><td><code>--json</code></td><td>Topology summary</td></tr><tr><td><code>graph</code></td><td><code>--format json</code></td><td><code>{ nodes, edges }</code></td></tr><tr><td><code>inspect</code></td><td><code>--json</code></td><td>One app descriptor</td></tr><tr><td><code>deps</code></td><td><code>--json</code></td><td>Shared dependency report</td></tr><tr><td><code>check</code></td><td><code>--json</code></td><td><code>{ valid, errors }</code></td></tr><tr><td><code>migrate</code></td><td><code>--json</code></td><td><code>{ migrations, pending }</code></td></tr></tbody></table><p>JSON is printed to stdout, pretty-printed with two-space indentation. Warnings (for example a configuration-loading fallback or a missing <code>remotes</code> block) are printed to stderr and do not corrupt JSON on stdout.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The diagnostic commands (<code>status</code>, <code>graph</code>, <code>inspect</code>, <code>deps</code>, <code>check</code>, <code>migrate</code>) print a Node.js object inspection — not JSON — when the JSON flag is omitted. Always pass the JSON flag in scripts.</p></div><p><code>init</code>, <code>generate</code>, <code>dev</code>, <code>build</code>, and <code>test</code> have no JSON mode.</p><h2 id="package-manager-selection" tabindex="-1">Package manager selection <a class="header-anchor" href="#package-manager-selection" aria-label="Permalink to &quot;Package manager selection&quot;">​</a></h2><p>Commands that run scripts (<code>dev</code>, <code>build</code>, <code>test</code>, and the root scripts written by <code>generate</code>) use <code>defaults.packageManager</code> from the configuration (<code>bun</code>, <code>pnpm</code>, or <code>npm</code>; default <code>bun</code>). The generated command shapes are:</p><table tabindex="0"><thead><tr><th>Purpose</th><th>bun / pnpm</th><th>npm</th></tr></thead><tbody><tr><td>Run a workspace package script</td><td><code>&lt;pm&gt; --filter &lt;package&gt; &lt;script&gt;</code></td><td><code>npm run &lt;script&gt; --workspace=&lt;package&gt;</code></td></tr><tr><td>Run a root script</td><td><code>&lt;pm&gt; run &lt;script&gt;</code></td><td><code>npm run &lt;script&gt;</code></td></tr><tr><td>Execute a local binary</td><td><code>bunx &lt;bin&gt;</code> / <code>pnpm exec &lt;bin&gt;</code></td><td><code>npx &lt;bin&gt;</code></td></tr></tbody></table><h2 id="programmatic-api" tabindex="-1">Programmatic API <a class="header-anchor" href="#programmatic-api" aria-label="Permalink to &quot;Programmatic API&quot;">​</a></h2><p>The package entry point (<code>import ... from &#39;mfe-forge&#39;</code>) exports <code>defineConfig</code>, <code>loadConfig</code>, <code>runDoctor</code>, <code>CliError</code>, <code>ExitCode</code>, and the types <code>MFEConfig</code>, <code>AppContext</code>, <code>ProjectContext</code>, <code>RemoteApp</code>, <code>DoctorCheck</code>, <code>DoctorReport</code>, and <code>CheckStatus</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../config">Configuration reference</a></li><li><a href="./../quick-start">Quick start</a></li><li><a href="./../troubleshooting">Troubleshooting</a></li></ul>`,36)])])}const m=t(c,[["render",i]]);export{g as __pageData,m as default};
